package com.shopstream.serde;

import com.shopstream.events.OrderCreated;
import org.apache.kafka.common.errors.SerializationException;
import org.apache.kafka.common.serialization.Serializer;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.json.JsonMapper;

public class OrderCreatedSerializer implements Serializer<OrderCreated> {

    private final JsonMapper mapper = JsonMapper.builder().build();

    @Override
    public byte[] serialize(String topic, OrderCreated event) {
        if (event == null) {
            return null; // a null value must stay a Kafka null (a tombstone)
        }
        try {
            return mapper.writeValueAsBytes(event);
        } catch (JacksonException e) {
            throw new SerializationException("Cannot serialize OrderCreated for " + topic, e);
        }
    }
}

