import org.apache.kafka.common.serialization.Deserializer;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.json.JsonMapper;

public class OrderCreatedDeserializer implements Deserializer<OrderCreated> {

    private final JsonMapper mapper = JsonMapper.builder().build();

    @Override
    public OrderCreated deserialize(String topic, byte[] data) {
        if (data == null) {
            return null;
        }
        try {
            return mapper.readValue(data, OrderCreated.class);
        } catch (JacksonException e) {
            throw new SerializationException("Cannot deserialize OrderCreated from " + topic, e);
        }
    }
}

