package com.shopstream.avro;

import com.shopstream.events.avro.OrderCreated;
import com.shopstream.events.avro.OrderLine;
import io.confluent.kafka.serializers.KafkaAvroSerializer;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;
import java.util.Properties;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.serialization.StringSerializer;

public class AvroOrderProducer {

    public static void main(String[] args) {
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class);
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, KafkaAvroSerializer.class);
        props.put("schema.registry.url", "http://localhost:8081");

        OrderLine line = OrderLine.newBuilder()
                .setSku("SKU-RED-SHOE-42")
                .setQty(2)
                .setUnitPrice(new BigDecimal("499.00"))
                .build();

        OrderCreated event = OrderCreated.newBuilder()
                .setEventId("6f1c2d4e-8a47-4d58-9d0e-3b2f6c1a9e10")
                .setOrderId("o-1001")
                .setCustomerId("c-77")
                .setLines(List.of(line))
                .setTotal(new BigDecimal("998.00"))
                .setOccurredAt(Instant.parse("2026-10-08T10:15:30Z"))
                .build();

        try (KafkaProducer<String, OrderCreated> producer = new KafkaProducer<>(props)) {
            producer.send(new ProducerRecord<>("orders", event.getOrderId(), event));
            producer.flush();
        }
    }
}

Properties props = new Properties();
props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
props.put(ConsumerConfig.GROUP_ID_CONFIG, "notification-service");
props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, KafkaAvroDeserializer.class);
props.put("schema.registry.url", "http://localhost:8081");
props.put("specific.avro.reader", true);

try (KafkaConsumer<String, OrderCreated> consumer = new KafkaConsumer<>(props)) {
    consumer.subscribe(List.of("orders"));
    for (ConsumerRecord<String, OrderCreated> r : consumer.poll(Duration.ofSeconds(5))) {
        System.out.printf("%s total=%s%n", r.key(), r.value().getTotal());
    }
}

