option java_multiple_files = true;
message OrderLine {
  string sku = 1;
  int32 qty = 2;
  int64 unit_price_minor = 3;   // amount in paise: 49900 means INR 499.00
}

message OrderCreated {
  string event_id = 1;
  string order_id = 2;
  string customer_id = 3;
  repeated OrderLine lines = 4;
  int64 total_minor = 5;
  string currency = 6;
  google.protobuf.Timestamp occurred_at = 7;
}

